import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiArrowRight, FiBriefcase, FiLogOut, FiMapPin, FiUser } from 'react-icons/fi';
import BrandMark from '../components/common/BrandMark';
import EmptyState from '../components/common/EmptyState';
import ErrorMessage from '../components/common/ErrorMessage';
import LoadingSpinner from '../components/common/LoadingSpinner';
import { useAuth } from '../hooks/useAuth';
import { getClientSites, getClientProfile } from '../services/siteService';

const SiteSelection = () => {
  const [sites, setSites] = useState([]);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const load = async () => {
    setLoading(true);
    try {
      const [sitesData, profileData] = await Promise.all([
        getClientSites(),
        getClientProfile()
      ]);
      setSites(sitesData.sites || []);
      setProfile(profileData.client || null);
      setError('');
    } catch (err) {
      setError(err.response?.data?.error || 'Unable to load project sites.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  if (loading) return (
    <div className="portal-page grid place-items-center">
      <LoadingSpinner message="Loading your projects…" />
    </div>
  );

  if (error) return (
    <div className="portal-page grid place-items-center">
      <ErrorMessage message={error} onRetry={load} />
    </div>
  );

  return (
    <div className="portal-page">
      <div className="portal-shell selection-shell">

        {/* ========== SIDEBAR ========== */}
        <aside className="portal-sidebar selection-sidebar">
          <div className="flex items-center gap-2 px-4 py-3">
            <BrandMark />
            <div className="text-xs">
              <div className="font-bold text-textPrimary">Aeroview 360</div>
              <div className="text-[10px] text-textMuted">Client Portal</div>
            </div>
          </div>

          <div className="portal-rule" />

          {/* ✅ Client Logo in Sidebar */}
          <div className="flex items-center gap-3 px-4 py-3">
            {profile?.company_logo ? (
              <img
                src={profile.company_logo}
                alt={profile.client_name}
                className="w-10 h-10 rounded-lg object-cover border border-gray-200"
              />
            ) : (
              <div className="w-10 h-10 rounded-lg bg-primaryDark text-white flex items-center justify-center font-bold text-sm">
                {profile?.client_name?.slice(0, 2).toUpperCase()}
              </div>
            )}
            <div className="min-w-0">
              <div className="font-semibold text-sm text-textPrimary truncate">
                {profile?.client_name || 'Client'}
              </div>
              <div className="text-[10px] text-textMuted uppercase tracking-wider">Client Workspace</div>
            </div>
          </div>

          <div className="portal-rule" />

          <div className="px-4 py-2 text-xs text-textSecondary space-y-1">
            <p className="flex items-center gap-2"><FiBriefcase /> Project progress records</p>
            <p className="flex items-center gap-2"><FiMapPin /> Site-specific access</p>
          </div>

          <div className="portal-rule" />

          <div className="portal-client px-4 py-3">
            <span className="text-xs text-textMuted">Signed in as</span>
            <strong className="text-sm block">{user?.name}</strong>
            <button
              onClick={() => { logout(); navigate('/login'); }}
              className="mt-2 text-sm text-red-500 hover:text-red-700"
            >
              <FiLogOut className="inline mr-1" /> Sign out
            </button>
          </div>
        </aside>

        {/* ========== MAIN CONTENT ========== */}
        <main className="portal-main selection-main">
          {/* ✅ Header with Client Logo */}
          <div className="selection-head flex items-center gap-4 mb-4">
            <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-gray-200 flex-shrink-0">
              {profile?.company_logo ? (
                <img
                  src={profile.company_logo}
                  alt={profile.client_name}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full bg-gray-200 flex items-center justify-center text-gray-500 font-bold text-xl">
                  {profile?.client_name?.slice(0, 2).toUpperCase() || 'C'}
                </div>
              )}
            </div>
            <div>
              <h1 className="text-xl font-bold text-textPrimary">Welcome Back!</h1>
              <p className="text-sm text-textSecondary">Select a site to access your dashboard</p>
            </div>
          </div>

          <div className="portal-rule mb-4" />

          {sites.length === 0 ? (
            <EmptyState message="No project sites are available for your client account yet." />
          ) : (
            <div className="site-list space-y-3">
              {sites.map((site) => (
                <button
                  key={site.site_id}
                  onClick={() => navigate(`/sites/${site.site_id}/360-tour`)}
                  className="site-choice flex items-center justify-between w-full p-4 bg-white rounded-xl border border-gray-200 hover:border-primaryDark hover:shadow-md transition-all text-left"
                >
                  <div className="flex items-center gap-3">
                    <span className="site-choice__icon text-primaryDark">
                      <FiBriefcase size={20} />
                    </span>
                    <span>
                      <strong className="text-textPrimary">{site.site_name || 'Unnamed Site'}</strong>
                      <small className="block text-textSecondary text-sm">
                        {site.location || 'Click to access dashboard'} · {site.status || 'Active'}
                      </small>
                    </span>
                  </div>
                  <FiArrowRight className="text-textMuted group-hover:text-primaryDark transition-all" />
                </button>
              ))}
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default SiteSelection;
